# Additional RA10 practice set tasks for Unit 6 (Principles of Management / leadership and management). 8 original cases.
from ra10_sets import p, h, grid, cap, paper, u6_acts


def build(c):
    A = [h('Part A Set Task Information'), h(c['name']), p(c['intro']), p(c['goals'])]
    for t in c['story']:
        A.append(p(t))
    A += [grid(c['t1'][0], c['t1'][1]), cap(c['t1'][2]), grid(c['t2'][0], c['t2'][1]), cap(c['t2'][2]), p(c['rival'])]
    B = [h('Set Task'), p('You must complete both activities.')]
    acts = u6_acts('%s, %s' % (c['owner'], c['owner_role']), (c['r1'], c['who']), (c['r2'], c['who']), None)
    return paper('U6-R%d' % c['k'], 6, '99%02d' % c['k'], c['name'], c['theme'], 88, acts, A, B)


